"Abstand 2":"მანძილი 2",
"Abstand Anfang / Ende":"დაშორება დასაწყისი / ბოლო",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"დასაწყისიდან / ბოლოდან დაშორება ფლანგს ნაწილობრივ ფლანგად აქცევს. ესკიზში დამატებითი დახურული პროფილები ფირფიტაში ამონაჭრებად იქცევა. ხვრელები და ფანჯრები ფლანგში: ცენტრი წიბოს გასწვრივ (მრუდი წიბოს შემთხვევაში რკალის გასწვრივ), ცენტრი მოღუნვის ბოლოდან, ზომა – ისინი გაშლაშიც ჩანს. თუ მრუდი წიბო გადატეხის გარეშე გადადის მეზობელ წიბოში და ორივეს აქვს ფლანგი ერთნაირი მოღუნვის კუთხით, ფლანგები გასათავისუფლებელი ამონაჭრის გარეშე გადადის ერთმანეთში. „კონტური ესკიზიდან“ ესკიზის დახურულ პროფილებს ფლანგიდან ჭრის: მისი X წიბოს გასწვრივ მიდის, მისი Y – ფლანგის შიგნით, ნულოვანი წერტილი წიბოს დასაწყისშია, მოღუნვის ბოლოზე (გადაადგილებადია).",
