"Bei „Bohrungen“ liegt das Teil auf der Fläche an dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"„ხვრელების“ რეჟიმში დეტალი წახნაგზე დევს ხვრელის იმ ბოლოსთან, რომელიც წკაპუნის წერტილთან უფრო ახლოა. დააწკაპუნეთ რამდენიმე ხვრელზე ზედიზედ, შემდეგ „მზადაა“.",
"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"„ხვრელების“ რეჟიმში დეტალი ხვრელის იმ ბოლოში ზის გასწორებულად, რომელიც წკაპუნის წერტილთან უფრო ახლოა. დააწკაპუნეთ რამდენიმე ხვრელზე ზედიზედ, შემდეგ „მზადაა“.",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"„ხვრელების“ რეჟიმში თავი ხვრელის იმ მხარესაა, რომელიც წკაპუნის წერტილთან უფრო ახლოა; ტანი ხვრელში მიდის. დააწკაპუნეთ რამდენიმე ხვრელზე ზედიზედ, შემდეგ „მზადაა“.",
