"Das Bild konnte nicht gelesen werden.":"სურათის წაკითხვა ვერ მოხერხდა.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"სურათი შაბლონად დევს სიბრტყეზე. ზომა, მდებარეობა, ბრუნვა და გაუმჭვირვალობა შემდეგ თვისებების ფანჯარაში დააყენეთ (მაგ. სიგანე ცნობილი ზომის მიხედვით).",
"Das Ergebnis des Geometriekerns ist unlesbar":"გეომეტრიული ბირთვის შედეგი წაუკითხავია",
"Das Ergebnis konnte nicht geschrieben werden":"შედეგის ჩაწერა ვერ მოხერხდა",
"Das Maß muss größer als 0 sein.":"ზომა 0-ზე მეტი უნდა იყოს.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"ბადე რჩება სამკუთხედების ბადედ (არა B-Rep). რედაქტირება განყოფილებაში ბადე: შეკეთება, შემცირება, გასწორება, სიბრტყით ჭრა … წარმოებაში 3D ფრეზირების სტრატეგიებს შეუძლიათ მისი უშუალოდ დამუშავება.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"ბადეს აქვს {0} სამკუთხედი. თითოეული სხეულის წახნაგი გახდება – ეს დიდხანს გრძელდება და სხეულს ანელებს. ჯერ „შემცირება“ ჩვეულებრივ უკეთესია.\n\nმაინც გარდაიქმნას?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"ბადე დახურული არ არის. ჯერ შეასრულეთ „შეკეთება“ – სხეულს დახურული გარსი სჭირდება.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"ბადე Z-ში {0}-დან {1} mm-მდე, X-ში {2}-დან {3} mm-მდე, Y-ში {4}-დან {5} mm-მდე ვრცელდება. წერტილები, რომლებიც წრფიდან ტოლერანტობაზე ნაკლებად გადაიხრება, ამოიშლება.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"პროფილმა ღერძი არ უნდა გადაკვეთოს. ესკიზში ღია ხაზი შეიძლება ღერძად გამოდგეს.",
"Das Profil mit den jetzigen Werten überschreiben":"პროფილის გადაწერა მიმდინარე მნიშვნელობებით",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"პროფილი წრფის/პოლიხაზის გასწვრივ მიჰყავთ. პროფილი უმჯობესია ტრაექტორიის დასაწყისის მართობულად დახაზოთ (მაგ. პროფილი XZ-ზე, ტრაექტორია XY-ზე).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"პროფილი ესკიზის სიბრტყიდან ამოზნექილად ან ჩაღრმავებულად იტვიფრება.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"ნამზადი არის პარალელეპიპედი არჩეული სხეულის გარშემო (პლუს მარაგი).",
"Das Setup hat keine Operationen.":"სეტაპს ოპერაციები არ აქვს.",
"Das Teil ist für die Senkung zu dünn (Senktiefe {0} mm, Dicke {1} mm).":"ნაწილი ჩაღრმავებისთვის ძალიან თხელია (ჩაღრმავების სიღრმე {0} mm, სისქე {1} mm).",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"ხელსაწყო ფრეზავს წრეებით, რომელთა ცენტრი ღარის გასწვრივ მოძრაობს. ის არასოდეს არის მთელი სიგანით შეხებაში — ეს დიდ ჭრის სიღრმეს იძლევა და ზოგავს ფრეზასა და შპინდელს. ფრეზას ღარის სიგანის დაახლოებით 60 % უნდა ჰქონდეს.",
"Das Werkzeug schneidet die Fläche nicht":"ხელსაწყო ზედაპირს არ კვეთს",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"ხელსაწყო ჭრის არჩეული წახნაგების მიმართულებით, სანამ მითითებულ მარაგებს არ მიაღწევს.",
