"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"ხელსაწყო თავს არიდებს ამ წახნაგებს, როცა ახლოს მდებარე წახნაგებს ამუშავებს, და იცავს უსაფრთხო მანძილებს.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"პირველი Esc აუქმებს მხოლოდ ხელსაწყოს ან მონიშვნას – ზედმეტი Esc ესკიზს არ ხურავს",
