"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"ხრახნის საფრეზი სრულ მასალაში მუშაობს: ჯერ გაათავისუფლეთ წვერი ფრეზირებით (2D კონტური წვერის გარშემო გარედან ხრახნის სიღრმემდე).",
