"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"სხეული გადმოიტანება ბადედ ჩვენების სამკუთხედებით. თვით სხეული ინახება; სხეულის შემდგომი ცვლილებები ბადეს არ ცვლის.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"სხეული მისი ვერტიკალური ცენტრალური ღერძის გარშემო იზომება და სამაგრის კონტურად (მონაკვეთები) დოკუმენტის ხელსაწყოთა ბიბლიოთეკაში ინახება.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"წერტილი, რომლის გარშემოც ხედი ბრუნავს (თავისუფალი ორბიტისას). „ისრის ქვეშ“: მოდელის ადგილი, საიდანაც ბრუნვა იწყება.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"რადიუსი თანაბრად იზრდება ყოველი არჩეული წიბოს დასაწყისიდან ბოლომდე. რომელი ბოლოა დასაწყისი, წიბო განსაზღვრავს – საჭიროებისას გაცვალეთ.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"წახნაგის კიდე ჩაკეტილი ჯაჭვია: „უწყვეტად“ რადიუსი ერთხელ მთელ გარშემოწერილობაზე იცვლება, ამ ოფციის გარეშე კი თითოეულ წიბოზე ცალ-ცალკე საწყისი რადიუსიდან საბოლოომდე.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"ჭრა არც ერთ სხეულს არ ეხება – მასალა არ მოიხსნება.",
