"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"პირველი მანძილი იზომება იმ წახნაგზე, რომელიც უფრო მეტად ზემოთაა მიმართული (Z), მეორე მანძილი ან კუთხე კი მეორე წახნაგს ეხება. „მხარეების გაცვლა“ ამას უკუაქცევს. მხებად მიმდებარე წიბოები თან მიჰყვება.",
