"Die Ebene berührt den Zylinder; der Winkel dreht die Berührlinie um die Zylinderachse, gemessen von der Bezugsebene.":"სიბრტყე ეხება ცილინდრს; კუთხე ახვევს შეხების ხაზს ცილინდრის ღერძის გარშემო და იზომება საბაზო სიბრტყიდან.",
"Die Ebene geht durch alle drei Punkte; Skizzen darauf wandern mit, wenn du die Punkte änderst.":"სიბრტყე სამივე წერტილზე გადის; მასზე არსებული ესკიზები მასთან ერთად გადაადგილდება, თუ წერტილებს შეცვლით.",
"Die Ebene schneidet das Netz nicht.":"სიბრტყე ბადეს არ კვეთს.",
