"Die Fläche hat auf dieser Ebene keinen Rand (sie steht senkrecht dazu).":"წახნაგს ამ სიბრტყეზე კიდე არ აქვს (ის მასზე მართობულია).",
"Die Fläche ist kleiner als der Bahnabstand":"წახნაგი გვერდით ბიჯზე პატარაა",
