"Die Kanten müssen einen geschlossenen Rand bilden (z. B. die offene Öffnung eines Rohrs). Die neue Fläche spannt sich hinein – auch gewölbt. „Tangential“ lässt sie glatt an die Nachbarflächen anschließen.":"წიბოებმა დახურული კიდე უნდა შექმნან (მაგ. მილის ღია ბოლო). ახალი ზედაპირი მასში იჭიმება – მრუდადაც. „მხებად“ მას მეზობელ წახნაგებთან გლუვად აერთებს.",
"Die Komponente bewegt sich relativ zu ihrem Bezug. Die Bewegungsstudie fährt den Bereich ab und prüft dabei auf Kollisionen.":"კომპონენტი მოძრაობს თავისი საბაზო კომპონენტის მიმართ. მოძრაობის კვლევა გადის მთელ დიაპაზონს და ამასთან ამოწმებს შეჯახებებს.",
"Die Kontur liegt in Z nicht am Teil":"კონტური Z-ში ნაწილზე არ არის",
"Die Kontur liegt weit außerhalb des Rohteils":"კონტური ნამზადს საგრძნობლად სცდება",
"Die Linie wird in der Skizzenebene auf die Dicke verbreitert und senkrecht zur Skizze um die Höhe extrudiert (negativ = andere Seite).":"ხაზი ესკიზის სიბრტყეში სისქემდე ფართოვდება და ესკიზის მართობულად სიმაღლეზე ამოიწევა (უარყოფითი = მეორე მხარე).",
"Die Maschine hält an (M0), zum Beispiel zum Umspannen oder Späne entfernen. Die nächste Operation schaltet Spindel und Kühlmittel wieder ein. Der Text steht als Kommentar davor.":"დაზგა ჩერდება (M0), მაგალითად, გადასამაგრებლად ან ბურბუშელის მოსაცილებლად. შემდეგი ოპერაცია შპინდელსა და გაგრილებას ისევ რთავს. ტექსტი კომენტარად წინ წერია.",
"Die Maschine wartet die angegebene Zeit.":"დაზგა მითითებულ დროს ელოდება.",
