"Die NC-Prüfung rechnet für geschwenkte Setups (3+2) die Achswinkel nach, prüft die Achsgrenzen und ob Werkzeug, Halter oder Spindelnase in den Maschinentisch fahren.":"NC შემოწმება დახრილი სეტაპებისთვის (3+2) ხელახლა ითვლის ღერძების კუთხეებს, ამოწმებს ღერძების საზღვრებს და შედის თუ არა ხელსაწყო, სამაგრი ან შპინდელის ცხვირი დაზგის მაგიდაში.",
