"Die Schraube reicht nicht bis in das unterste Teil (Länge {0} mm, darüber {1} mm).":"ჭანჭიკი ყველაზე ქვედა დეტალამდე არ აღწევს (სიგრძე {0} mm, მის ზემოთ {1} mm).",
"Die Seitenwände neigen sich um diesen Winkel. Positiv: der Körper wird von der Skizze weg breiter, negativ: schmaler (Entformungsschräge).":"გვერდითი კედლები ამ კუთხით იხრება. დადებითი: სხეული ესკიზიდან დაშორებისას ფართოვდება, უარყოფითი: ვიწროვდება (ფორმიდან ამოღების დახრა).",
"Die Skizze beschreibt die Schneidkante: X = Radius, Y = Höhe über der Spitze (die Y-Achse ist die Werkzeugachse). Gespiegelte Hälften werden zusammengefasst.":"ესკიზი აღწერს ჭრის წიბოს: X = რადიუსი, Y = სიმაღლე წვერიდან (Y ღერძი ხელსაწყოს ღერძია). სარკისებური ნახევრები გაერთიანდება.",
