"Die fertige Bahn wird an den weiteren Stellen wiederholt (Maße ab Werkstück-Nullpunkt). Das Modell und das Rohteil müssen dort Material haben – die Simulation zeigt es.{0}":"დასრულებული ტრაექტორია გამეორდება დანარჩენ ადგილებზე (ზომები სამუშაო ნაწილის ნულოვანი წერტილიდან). მოდელსა და ნამზადს იქ მასალა უნდა ჰქონდეს — სიმულაცია აჩვენებს.{0}",
"Die gespiegelte Form berührt den Körper nicht – es entsteht ein loses Stück.":"ასახული ფორმა სხეულს არ ეხება – გამოყოფილი ნაჭერი წარმოიქმნება.",
"Die gewählte ebene Fläche wird durch die Zielebene ersetzt: Der Körper wächst bis zu ihr oder wird bis zu ihr gekürzt, die Seitenwände laufen gerade weiter. Mit einer geneigten Konstruktionsebene wird die Fläche schräg.":"არჩეული ბრტყელი წახნაგი სამიზნე სიბრტყით იცვლება: სხეული მასამდე იზრდება ან მასამდე იკვეცება, გვერდითი კედლები სწორად გრძელდება. დახრილი საკონსტრუქციო სიბრტყით წახნაგი დახრილი გახდება.",
"Die gewählten Flächen bekommen eine Dicke entlang ihrer Normalen – auch gewölbte Flächen. Angrenzende Flächen werden zu einem Stück verbunden.":"არჩეული წახნაგები სისქეს იღებს ნორმალის გასწვრივ – მრუდი წახნაგებიც. მიმდებარე წახნაგები ერთ ნაჭრად ერთიანდება.",
