"Dreh-Setup mit Fräs-Postprozessor – bitte einen Dreh-Postprozessor wählen.":"სახარატო სეტაპი ფრეზირების პოსტპროცესორით – აირჩიეთ სახარატო პოსტპროცესორი.",
