"Drehen":"ტორნვა",
"Drehen - Bohren":"ტორნვა – გაბურღვა",
"Drehen - Einstechen":"ტორნვა – ჩაჭრა",
"Drehen - Gewinde":"ტორნვა – ხრახნი",
"Drehen - allgemein":"ტორნვა – ზოგადი",
"Drehen um":"ბრუნვა წერტილის გარშემო",
"Drehen um die Kappe":"გრეხა თავაკის გარშემო",
"Drehen umkehren":"ბრუნვის შებრუნება",
"Drehen: C-Achse und angetriebenes Werkzeug ein":"ხარატობა: C ღერძი და ამძრავიანი ხელსაწყო ჩართულია",
"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"ხარატობა: დეტალი უნდა იყოს Z ღერძის მიმართ ბრუნვით სიმეტრიული. Z0 = ზედა ბოლო წახნაგი, X = დიამეტრი.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"ბრუნვა: დააწკაპუნეთ ბრუნვის წერტილზე, შემდეგ თაგვით მიუთითეთ კუთხე (გადახედვა). Esc ასრულებს.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"ხარატობა: დიამეტრი, რომელზეც რევოლვერი გადაირთვება (Okuma, LinuxCNC). 0 = ნამზადის Ø + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"შებრუნება: აირჩიეთ ელემენტები, შემდეგ დააწკაპუნეთ ბრუნვის წერტილზე და მაუსით მიუთითეთ კუთხე (გადახედვა); ასლადაც",
"Drehen: Gewindeschnitt":"ხარატობა: ხრახნის ჭრა",
"Drehen: Gewindezyklus":"ხარატობა: ხრახნის ციკლი",
"Drehen: Polar-Interpolation aus":"ხარატობა: პოლარული ინტერპოლაცია გამორთულია",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"ხარატობა: პოლარული ინტერპოლაცია ჩართულია (X დიამეტრი, C მმ-ში; ცარიელი = X/C გრადუსებში)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"ხარატობა: დამასრულებელი დამუშავების ციკლი (უხეში დამუშავების ციკლის კონტური)",
"Drehen: Schruppzyklus ({contour} = Konturzeilen)":"ხარატობა: უხეში დამუშავების ციკლი ({contour} = კონტურის სტრიქონები)",
"Drehen: Vorsatz erste Konturzeile":"ხარატობა: კონტურის პირველი სტრიქონის პრეფიქსი",
"Drehen: Vorsatz letzte Konturzeile":"ხარატობა: კონტურის ბოლო სტრიქონის პრეფიქსი",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"ბრუნვა: კუთხე (°, საათის ისრის საწინააღმდეგოდ); ბრუნვის წერტილი X; ბრუნვის წერტილი Y; ასლები (0 = ბრუნვა)",
"Drehen: Y-Achse aus":"ხარატული დამუშავება: Y ღერძი გამორთულია",
"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"ხარატული დამუშავება: Y ღერძი ჩართულია (სიბრტყე X/Y; აქვე ჩაწერეთ დაზგის C-დამჭერი)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"ხარატობა: Z ბოლო წახნაგის წინ, რომელზეც რევოლვერი გადაირთვება. 0 = უსაფრთხო მანძილი + 100 mm",
"Drehen: Zylinder-Interpolation aus":"ხარატობა: ცილინდრული ინტერპოლაცია გამორთულია",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"ხარატობა: ცილინდრული ინტერპოლაცია ჩართულია ({cylr} = რადიუსი; ცარიელი = Z/C ამის გარეშე)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"ხარატობა: ამძრავიანი ხელსაწყო და C ღერძი გამორთულია",
"Drehen: einen Winkel angeben.":"ბრუნვა: მიუთითეთ კუთხე.",
