"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"საკუთარი მალსახმობები: ხელსაწყოთა პანელზე გახსენით ჯგუფის მენიუ (▾), ბრძანებასთან დააწკაპუნეთ ⋮ → „კლავიატურის მალსახმობის შეცვლა …“.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"საკუთარი ზომები და შენიშვნები ფურცელზე თაგვით გადაიტანება (ზომის ხაზის მანძილი, გამოსატანი ხაზის კუთხე, კუთხის რკალის რადიუსი). ორ კუთხეზე დაწკაპუნება = სიგრძის ზომა. წრეწირის კიდეზე დაწკაპუნება ხედში ზემოდან = დიამეტრი (ან რადიუსი). კუთხე: ჯერ წვერო, შემდეგ თითო კუთხის წერტილი ორივე გვერდზე. ფასკა: დახრილი წიბოს ორივე ბოლო – მიიღება, მაგ., 2×45°. თითოეული ზომის შემდეგ ტექსტურ ველში მითითებულია დამატება, როგორიცაა ±0,1, H7 ან 4×.",
