"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"ჯერ დააწკაპუნეთ წიბოზე იმ სხეულზე, რომელიც გადაადგილდება, შემდეგ სამიზნე წიბოზე მეორე სხეულზე. სწორი წიბოები ერთმანეთს ემთხვევა (შუა შუაზე); წრიული წიბოების შემთხვევაში – ხვრელი და ბრჯენი – ღერძები ერთნაირად მიმართება და ცენტრები ერთიანდება.",
"Erst ein Setup anlegen.":"ჯერ შექმენით სეტაპი.",
"Erst ein Setup mit Operationen anlegen.":"ჯერ შექმენით სეტაპი ოპერაციებით.",
