"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"ჯერ შექმენით სხეული განყოფილებაში კონსტრუირება ან ჩაამატეთ ბადე (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"ჯერ შექმენით სხეული განყოფილებაში კონსტრუირება.",
