"Fläche anklicken – die Bohrung entsteht mit":"დააწკაპუნეთ წახნაგზე – ხვრელი ერთდროულად იქმნება",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"დააწკაპუნეთ წახნაგზე: თითოეულ დაწკაპუნების წერტილში იქმნება ჭანჭიკის გამტარი ხვრელი (ISO 273, საშუალო სერია) ყველა ნაწილში, რომლებიც იქ ერთმანეთზე დევს – ჩაფლული თავის ჭანჭიკებისთვის 90°-იანი კონუსური ჩაღრმავებით, ცილინდრული თავის ჭანჭიკებისთვის სურვილისამებრ ცილინდრული ჩაღრმავებით (DIN 974-1, სერია 1) თავის სიღრმეზე. ჭანჭიკი მაშინვე ხვრელში ჯდება. ხვრელი და ჭანჭიკი შემდეგ დროის ღერძზე შეიძლება შეიცვალოს.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"დააწკაპუნეთ სხეულის წახნაგზე: მისი კიდე კონტურად ემატება ესკიზს. წიბოზე დაწკაპუნება მხოლოდ ამ წიბოს გადაპროექტებს (წრეწირები წრეწირებად რჩება). გადაპროექტებული გეომეტრია იისფერია.",
