"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"წახნაგები ნაწილის ბოლოზე (ორწახნაგა, ოთხკუთხა, ექვსკუთხა) ამძრავიანი თითისებრი ფრეზით Z-ის გასწვრივ. გასაღების ზომა = წახნაგის ბრუნვის ღერძიდან მანძილის ორმაგი. X და C ერთად მოძრაობს (პოლარული ინტერპოლაცია, Fanuc G12.1); პოსტპროცესორში ამ შაბლონის გარეშე გამოიტანება მოკლე X/C ნაბიჯები.",
