"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"ესკიზის სწორი ხაზები, რომლებიც არც ერთ პროფილს არ ეკუთვნის (დამხმარე ხაზებიც). მოღუნვა: ხაზი მოღუნვის ზონის შუაა, ესკიზი კი იქ გამოჭრილი ნამზადია – ფირფიტის უდიდესი ნაწილი ადგილზე რჩება, ხაზის მიღმა ყველაფერი თავისი ფლანგებით ერთად ტრიალდება. ხაზი მთელ ფირფიტაზე მოქმედებს. გამაგრების ნეკნი: ხაზის გასწვრივ ნეკნი, განივ კვეთაში და ბოლოებში მომრგვალებული; ფურცელი სისქეს ინარჩუნებს.",
