"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"დახურული: ორ მეზობელ წიბოზე ყურები კუთხის ბისექტრისამდე მიდის და იქ ღრეჩოს ტოვებს. კუთხის განტვირთვა იქაა, სადაც მოხრის ზონები იკვეთება – გაშლილ ფორმაზე და მოხრილ ნაწილზე. მოხრილ წიბოზე მდებარე ყურიც ნამდვილ კუთხეში ირიბად იჭრება (იქ კუთხის განტვირთვის გარეშე).",
