"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"თითოეული ესკიზის პირველი მრუდი – ღია ან დახურული. მრუდები გარსით ერთდება (ზედაპირი სისქის გარეშე).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"თითო ფურცელზე ერთი ფაილი. ტრაექტორია კონტურის გვერდით, ნარჩენში, ჭრილის სიგანის ნახევარი მანძილით (ფრეზირებისას ფრეზის ნახევრით) გადის; ამონაჭრები თავიანთი ნაწილის კონტურამდე იჭრება, ყოველი კონტური ნარჩენიდან შესასვლელი ჭრილით იწყება. ჟალუზები საკუთარ ხაზზე იჭრება. დამჭერი ხიდურები: კონტურზე ამდენი ადგილი რჩება გაუჭრელი (ლაზერი, პლაზმა, წყლის ჭავლი: სხივი იქ ითიშება; ფრეზირება: ფრეზი ფურცლის სისქის ნახევრამდე ამოდის); 40 mm-ზე მოკლე კონტურებს ისინი არ აქვთ. „მართვის სისტემა“ განსაზღვრავს, როგორ ირთვება და ითიშება სხივი; გაჩხვლეტის დრო პროგრამაში G4-ით იწერება, თუ მართვის სისტემა თავად არ ჩხვლეტს. ნულოვანი წერტილი ფურცლის მარცხენა ქვედა კუთხეა, ფრეზირებისას Z0 ფურცლის ზედა მხარეა. გამოყენებამდე პროგრამა შეამოწმეთ დანადგარზე ან NC სიმულატორში.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"თითოეული ღერძი ცალ-ცალკე: დააწკაპუნეთ წიბოზე, კუთხეზე, წახნაგზე ან ხვრელზე. დაუყენებელი ღერძები აიღება ნამზადის წერტილიდან.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"თითოეული ოპერაცია ქვეპროგრამად (LBL) პროგრამის ბოლოს, გამოძახება CALL LBL-ით",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"ესკიზის ყოველი წრეწირი ხვრელის ცენტრია. ბურღვა ხდება ესკიზის ნორმალის საპირისპიროდ (მასალაში).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"ესკიზის ყოველი წრეწირი მეორდება ცენტრის გარშემო (ესკიზის კოორდინატებში) შებრუნებით – წრეწირი გამყოფი წრეწირის რადიუსის დაშორებით ხვრელების წრიულ განლაგებას იძლევა.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"ესკიზის ყოველი წრეწირი ბადედ იქცევა: მანძილები ესკიზის X და Y მიმართულებით (უარყოფითიც შეიძლება).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"ახლა აირჩიეთ წერტილი მეორე გვერდზე.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"ახლა თითოეული მიმართულებით ერთხელ ბოლომდე: გადაწიეთ, გაწიეთ, დააჭირეთ, დახარეთ, გრიხეთ (10 წმ) …",
"Jetzt laden":"ახლა ჩამოტვირთვა",
