"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"კალიბრება: დააწკაპუნეთ სურათზე პირველ წერტილზე (Esc აუქმებს).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"კალიბრება: ორ წერტილს შორის რეალური მანძილი (მმ)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"კალიბრება: დააწკაპუნეთ სურათზე ორ წერტილზე, რომელთა შორის მანძილი ცნობილია, და შეიყვანეთ რეალური მანძილი – სურათი სწორ მასშტაბს მიიღებს.",
