"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"წიბო {0}: ფლანგი მოხრილ წიბოზე – მისი კიდე ფორმირებისას {1} %-ით იკუმშება (ნაოჭების საფრთხე); გაშლა იქ მიახლოებითია.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"წიბო {0}: ფლანგი მოხრილ წიბოზე – მისი კიდე ფორმირებისას {1} %-ით იჭიმება (ბზარების საფრთხე); გაშლა იქ მიახლოებითია.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"წიბო {0}: ფლანგის ზომა {1} mm მოღუნვაზე ({2} mm) მცირეა",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"წიბო {0}: რკალი ძალიან ვიწროა ამ ფლანგისთვის",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"წიბო {0}: დაშორებები ფლანგს არ ტოვებს.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"წიბო {0}: ფლანგი მოღუნვის ხაზს კვეთს – „დაშორება დასაწყისი / ბოლო“-თი დაასრულებინეთ მოღუნვამდე",
