"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"წიბო {0}: ამონაჭრი ეკუთვნის ფლანგს, რომელიც არ არსებობს.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"წიბო {0}: ფლანგში არსებული ამონაჭრი მოღუნვის გვერდით {1} mm-ზეა (ფურცლის სისქის 2 × -ზე ნაკლები) – მოღუნვისას ის დეფორმირდება.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"წიბო {0}: ამონაჭრი მოღუნვიდან {1} mm-ზეა (2 × ფურცლის სისქეზე ნაკლები) – მოღუნვისას დეფორმირდება.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"წიბო {0}: ამონაჭრი ფლანგის საზღვრებს სცდება.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"წიბო {0}{1}: ფლანგი {2} mm 2 × ფურცლის სისქეზე მოკლეა – მოღუნვის პრესზე თითქმის ვერ მოიღუნება.",
