"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"გაუშვით თავაკი და აირჩიეთ „ნულოვანი წერტილის კალიბრაცია“. შემდეგ სცადეთ თითოეული მიმართულება: ზოლი უნდა მოძრაობდეს, ხოლო უძრაობისას რჩებოდეს ნაცრისფერ მკვდარ ზონაში.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"თავაკის გადაწევა = გადაადგილება, დაჭერა/გაწევა = მასშტაბირება, დახრა და გრეხა = მოდელის ბრუნვა. ესკიზებში მხოლოდ გადაადგილება და მასშტაბირება. SpaceMouse Pro/Enterprise: T, F, R = ხედი ზემოდან, წინიდან, მარჯვნიდან. თუ არაფერი ხდება: 3Dconnexion-ის დრაივერი ხანმოკლედ დახურეთ და თავიდან დაუკავშირდით.",
