"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"კონტურები მუქი უბნების კიდეს მიჰყვება. ცენტრალური ხაზი შტრიხების შუაში გადის – გრავირებისთვის და ხაზოვანი ნახაზებისთვის შესაფერისია. „წრფეები, რკალები და წრეწირები“ ამოიცნობს სწორ წიბოებს, მკვეთრ კუთხეებს, მომრგვალებებს და წრეწირებს; „პოლიხაზები“ სურათს წერტილ-წერტილ მიჰყვება. მასშტაბი საჭიროებისას შემდეგ „შაბლონის კალიბრებით“ ან „მასშტაბირებით“ დაარეგულირეთ.",
