"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"ესკიზის მრუდები ბოლო ზედაპირზე (ბრუნვის ღერძის განივად) ამძრავიანი ფრეზით Z-ის გასწვრივ (X და C ერთად მოძრაობს; Fanuc: პოლარული ინტერპოლაცია G12.1). ღია მრუდები წინ და უკან ფრეზირდება. სიღრმე ბოლო ზედაპირიდან.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"ესკიზის მრუდები, რომლებიც ბრუნვის ღერძის გასწვრივ დევს, გარშემოწერილობაზე იხვევა და ღერძისკენ მიმართული ამძრავიანი ფრეზით ფრეზირდება (Z და C ერთად მოძრაობს; Fanuc: ცილინდრული ინტერპოლაცია G7.1). ესკიზის სიბრტყე განსაზღვრავს კუთხეს, რომელზეც კონტური მდებარეობს; ესკიზში ჰორიზონტალური მონაკვეთები ნაწილის გარშემო რკალებად იქცევა. სიღრმე გარე დიამეტრიდან.",
