"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"საყრდენი წერტილებით რადიუსი მითითებულ მნიშვნელობებზე გადის (მდებარეობა წიბოს სიგრძის %-ში). ამას დიდი გეომეტრიული ბირთვი ითვლის; პირველად ის რამდენიმე წამს იტვირთება.",
