"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"მზა ნაწილთან შედარება: მწვანე = ზომაზე, ლურჯი = დარჩენილი მასალა, წითელი = ზედმეტად ღრმა",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"მაუსი მიიტანეთ კონტურის გვერდით (მხარე განსაზღვრავს მიმართულებას) · Esc ასრულებს",
