"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"ჩამჭრელთან მხოლოდ ციკლი „ხრახნის ჭრა ჩამჭრელით“ – გაბურღვის ციკლი მას გატეხავდა",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"რამდენიმე გავლისას ხრახნის სიღრმე ფრეზირდება საფეხურებად, რომელთაგან თითოეული დაახლოებით თანაბარ ფენას იღებს — ეს ზოგავს პატარა ხრახნის ფრეზებს და მყარ მასალებს. უქმი გავლა ბოლო ტრაექტორიას კიდევ ერთხელ გადის ბიჯის გარეშე.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"NC პროგრამაში „გაბურღვის ციკლებით“ გამოიტანება მართვის ციკლები (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), სხვა შემთხვევაში — ფართოდ გაწერილი მოძრაობები.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"„ორიგინალის შენარჩუნებით“ ორიგინალი და სარკისებური ასახვა ერთ ბადედ იქცევა; სარკის სიბრტყეზე მდებარე წერტილები უერთდება – ღია ნახევრისგან ასე დახურული ნაწილი მიიღება.",
