"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"გავლა მხოლოდ კონტურის იმ ადგილებზე, რომლებსაც უფრო დიდი ფრეზი ვერ მიწვდა (შიდა კუთხეები, ვიწრო ადგილები). მისვლა/გასვლის რკალების, საჭერი ხიდურებისა და დამასრულებელი გავლების გარეშე; კორექცია კომპიუტერში.",
