"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"ღარი ბრუნვის ღერძის გასწვრივ (მაგ. სოლის ღარი) ღერძისკენ მიმართული ამძრავიანი ფრეზით; მთავარი შპინდელი ნაწილს C ღერძად აკავებს. ღარის სიგანე = ფრეზის Ø. საწყისი/ბოლო Z მოდელის Z-ში; თუ ღარი ბოლო ზედაპირამდე აღწევს, ფრეზა წინიდან შედის, სხვა შემთხვევაში დასაწყისში ჩაიძირება. სიღრმე გარე დიამეტრიდან.",
