"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"ჯიბე გარსზე ესკიზის დახურული კონტურებიდან, რომელიც ბრუნვის ღერძის გასწვრივ მდებარეობს (შიდა კონტურები კუნძულებად რჩება). ესკიზი დიამეტრზე ეხვევა; ღერძისკენ მიმართული ამძრავიანი ბოლოფრეზა მასალას შიგნიდან გარეთ იღებს (Z და C ერთად გადაადგილდება; Fanuc: ცილინდრული ინტერპოლაცია G7.1). ფრეზა რამპით შედის უშიდეს რგოლის გასწვრივ.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"ჯიბე ბოლო ზედაპირში ესკიზის დახურული კონტურებიდან (შიდა კონტურები კუნძულებად რჩება), ამძრავიანი თითისებრი ფრეზით Z-ის გასწვრივ. გაწმენდა შიგნიდან გარეთ მიმდინარეობს; ფრეზა ყველაზე შიდა ტრაექტორიის გასწვრივ დახრილად ეშვება და ერთი დონის ფარგლებში ქვემოთ რჩება. X და C ერთად მოძრაობს (Fanuc: პოლარული ინტერპოლაცია G12.1). სიღრმე ბოლო ზედაპირიდან.",
